import{_ as l,a0 as p,w as d,s as r,I as a,x as i,a1 as n,A as t,ao as h}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const V=JSON.parse('{"title":"使用 Vi/Vim 编辑器：高级概念 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Vi/Vim 编辑器：高级概念 | LCTT (201801) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Vi/Vim 编辑器：高级概念 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Vi/Vim 编辑器：高级概念 | LCTT (201801) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201801/20170524 Working with Vi-Vim Editor - Advanced concepts","title":"使用 Vi/Vim 编辑器：高级概念","tag":"201801","desc":""},"relativePath":"201801/20170524 Working with Vi-Vim Editor - Advanced concepts.md","filePath":"[post].md"}'),o={name:"201801/20170524 Working with Vi-Vim Editor - Advanced concepts.md"};function g(k,s,c,b,u,f){const e=p("Link");return d(),r("div",null,[s[18]||(s[18]=a("h1",{id:"使用-vi-vim-编辑器-高级概念",tabindex:"-1"},[i("使用 Vi/Vim 编辑器：高级概念 "),a("a",{class:"header-anchor",href:"#使用-vi-vim-编辑器-高级概念","aria-label":"Permalink to “使用 Vi/Vim 编辑器：高级概念”"},"​")],-1)),s[19]||(s[19]=a("p",null,"早些时候我们已经讨论了一些关于 VI/VIM 编辑器的基础知识，但是 VI 和 VIM 都是非常强大的编辑器，还有很多其他的功能可以和编辑器一起使用。在本教程中，我们将学习 VI/VIM 编辑器的一些高级用法。",-1)),a("p",null,[s[1]||(s[1]=i("（",-1)),s[2]||(s[2]=a("strong",null,"推荐阅读",-1)),s[3]||(s[3]=i("：[使用 VI 编辑器：基础知识] ",-1)),n(e,{href:"http://linuxtechlab.com/working-vi-editor-basics/"},{default:t(()=>[...s[0]||(s[0]=[i("1",-1)])]),_:1}),s[4]||(s[4]=i("）",-1))]),s[20]||(s[20]=h(`<h3 id="使用-vi-vim-编辑器打开多个文件" tabindex="-1">使用 VI/VIM 编辑器打开多个文件 <a class="header-anchor" href="#使用-vi-vim-编辑器打开多个文件" aria-label="Permalink to “使用 VI/VIM 编辑器打开多个文件”">​</a></h3><p>要打开多个文件，命令将与打开单个文件相同。我们只要添加第二个文件的名称。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span> $ vi file1 file2 file 3</span></span></code></pre></div><p>要浏览到下一个文件，我们可以（在 vim 命令模式中）使用：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:n</span></span></code></pre></div><p>或者我们也可以使用</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:e filename</span></span></code></pre></div><h3 id="在编辑器中运行外部命令" tabindex="-1">在编辑器中运行外部命令 <a class="header-anchor" href="#在编辑器中运行外部命令" aria-label="Permalink to “在编辑器中运行外部命令”">​</a></h3><p>我们可以在 vi 编辑器内部运行外部的 Linux/Unix 命令，也就是说不需要退出编辑器。要在编辑器中运行命令，如果在插入模式下，先返回到命令模式，我们使用 BANG 也就是 <code>!</code> 接着是需要使用的命令。运行命令的语法是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:! command</span></span></code></pre></div><p>这是一个例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:! df -H</span></span></code></pre></div><h3 id="根据模板搜索" tabindex="-1">根据模板搜索 <a class="header-anchor" href="#根据模板搜索" aria-label="Permalink to “根据模板搜索”">​</a></h3><p>要在文本文件中搜索一个单词或模板，我们在命令模式下使用以下两个命令：</p><ul><li>命令 <code>/</code> 代表正向搜索模板</li><li>命令 <code>?</code> 代表正向搜索模板</li></ul><p>这两个命令都用于相同的目的，唯一不同的是它们搜索的方向。一个例子是：</p><p>如果在文件的开头向前搜索，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:/ search pattern</span></span></code></pre></div><p>如果在文件末尾向后搜索，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:? search pattern</span></span></code></pre></div><h3 id="搜索并替换一个模式" tabindex="-1">搜索并替换一个模式 <a class="header-anchor" href="#搜索并替换一个模式" aria-label="Permalink to “搜索并替换一个模式”">​</a></h3><p>我们可能需要搜索和替换我们的文本中的单词或模式。我们不是从整个文本中找到单词的出现的地方并替换它，我们可以在命令模式中使用命令来自动替换单词。使用搜索和替换的语法是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:s/pattern_to_be_found/New_pattern/g</span></span></code></pre></div><p>假设我们想要将单词 “alpha” 用单词 “beta” 代替，命令就是这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:s/alpha/beta/g</span></span></code></pre></div><p>如果我们只想替换第一个出现的 “alpha”，那么命令就是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ :s/alpha/beta/</span></span></code></pre></div><h3 id="使用-set-命令" tabindex="-1">使用 set 命令 <a class="header-anchor" href="#使用-set-命令" aria-label="Permalink to “使用 set 命令”">​</a></h3><p>我们也可以使用 set 命令自定义 vi/vim 编辑器的行为和外观。下面是一些可以使用 set 命令修改 vi/vim 编辑器行为的选项列表：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:set ic  &#39; 在搜索时忽略大小写</span></span>
<span class="line"><span></span></span>
<span class="line"><span>:set smartcase &#39; 搜索强制区分大小写</span></span>
<span class="line"><span></span></span>
<span class="line"><span>:set nu &#39; 在每行开始显示行号</span></span>
<span class="line"><span></span></span>
<span class="line"><span>:set hlsearch &#39; 高亮显示匹配的单词</span></span>
<span class="line"><span></span></span>
<span class="line"><span>:set ro &#39; 将文件类型更改为只读</span></span>
<span class="line"><span></span></span>
<span class="line"><span>:set term &#39; 打印终端类型</span></span>
<span class="line"><span></span></span>
<span class="line"><span>:set ai &#39; 设置自动缩进</span></span>
<span class="line"><span></span></span>
<span class="line"><span>:set noai &#39; 取消自动缩进</span></span></code></pre></div><p>其他一些修改 vi 编辑器的命令是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:colorscheme &#39; 用来改变编辑器的配色方案 。（仅适用于 VIM 编辑器）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>:syntax on &#39; 为 .xml、.html 等文件打开颜色方案。（仅适用于VIM编辑器）</span></span></code></pre></div><p>这篇结束了本系列教程，请在下面的评论栏中提出你的疑问/问题或建议。</p><hr>`,34)),a("p",null,[s[6]||(s[6]=i("via: ",-1)),n(e,{href:"http://linuxtechlab.com/working-vivim-editor-advanced-concepts/"},{default:t(()=>[...s[5]||(s[5]=[i("http://linuxtechlab.com/working-vivim-editor-advanced-concepts/",-1)])]),_:1})]),a("p",null,[s[10]||(s[10]=i("作者：",-1)),n(e,{href:"http://linuxtechlab.com/author/shsuain/"},{default:t(()=>[...s[7]||(s[7]=[i("Shusain",-1)])]),_:1}),s[11]||(s[11]=i(" 译者：",-1)),n(e,{href:"https://github.com/geekpi"},{default:t(()=>[...s[8]||(s[8]=[i("geekpi",-1)])]),_:1}),s[12]||(s[12]=i(" 校对：",-1)),n(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[9]||(s[9]=[i("wxy",-1)])]),_:1})]),a("p",null,[s[15]||(s[15]=i("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[13]||(s[13]=[i("LCTT",-1)])]),_:1}),s[16]||(s[16]=i(" 原创编译，",-1)),n(e,{href:"https://linux.cn/"},{default:t(()=>[...s[14]||(s[14]=[i("Linux中国",-1)])]),_:1}),s[17]||(s[17]=i(" 荣誉推出",-1))])])}const C=l(o,[["render",g]]);export{V as __pageData,C as default};
